CREATE TABLE ezurlalias (id INT AUTO_INCREMENT NOT NULL, destination_url LONGTEXT NOT NULL, forward_to_id INT DEFAULT 0 NOT NULL, is_imported INT DEFAULT 0 NOT NULL, is_internal INT DEFAULT 1 NOT NULL, is_wildcard INT DEFAULT 0 NOT NULL, source_md5 VARCHAR(32) DEFAULT NULL, source_url LONGTEXT NOT NULL, INDEX ezurlalias_source_md5 (source_md5), INDEX ezurlalias_wcard_fwd (is_wildcard, forward_to_id), INDEX ezurlalias_forward_to_id (forward_to_id), INDEX ezurlalias_imp_wcard_fwd (is_imported, is_wildcard, forward_to_id), INDEX ezurlalias_source_url (source_url(191)), INDEX ezurlalias_desturl (destination_url(191)), PRIMARY KEY(id)) DEFAULT CHARACTER SET utf8 COLLATE `utf8_unicode_ci` ENGINE = InnoDB;
